// The built-in icon set (T04 §4.7): a generic subset of Tabler Icons (MIT, © Paweł Kuna; the licence is in
// THIRD-PARTY-NOTICES) under Tabler's own prefix `tabler`, so diagrams that use it render in any Mermaid that
// registers `@iconify-json/tabler`; a host's full `tabler` pack replaces it. `FA_FALLBACK` maps the most common Font
// Awesome names to look-alikes in it (`fa:fa-car` → `tabler:car`) for diagrams whose host registers no Font Awesome
// pack. Both are generated by tools/build-icons.mjs; this module is a lazy chunk of its own (core/icons/registry.ts).
import pack from './builtin.json' with { type: 'json' };
import fa from './fa-fallback.json' with { type: 'json' };
import type { IconifyJSON } from '../core/icons/types.js';

export const BUILTIN_ICONS: IconifyJSON = pack as IconifyJSON;
export const FA_FALLBACK: Readonly<Record<string, string>> = fa as Record<string, string>;
